Lemma in_carve_cp : forall au csz nnew cp, au mod 16 = 0 -> csz mod 32 = 0 -> 0 <= au -> 0 < csz -> 0 <= nnew ->
  In cp (carve_asc au csz 0 (Z.to_nat nnew)) -> exists j, 0 <= j < nnew /\ cp * 16 = au + j * csz /\ 0 <= cp.
Proof.
